import hashlib
import hmac
import time
import os
import sqlite3
from functools import wraps

# Permission levels
PERM_NONE = 0
PERM_READ = 1
PERM_WRITE = 2
PERM_ADMIN = 3

class SecureDocumentVault:
    """Enterprise document management system with role-based access control."""

    def __init__(self, db_path=':memory:'):
        self.db = sqlite3.connect(db_path)
        self.db.row_factory = sqlite3.Row
        self._init_schema()
        self._api_secret = os.urandom(32)
        self._session_store = {}
        # Precompute a dummy password hash to defend against timing-based
        # username enumeration. Verifying against this when a user does not
        # exist keeps the authentication path's timing roughly constant.
        self._dummy_hash = self._hash_password(os.urandom(16).hex())

    def _init_schema(self):
        self.db.executescript("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY,
                username TEXT UNIQUE NOT NULL,
                password_hash TEXT NOT NULL,
                department TEXT NOT NULL,
                is_active INTEGER DEFAULT 1
            );
            CREATE TABLE IF NOT EXISTS documents (
                id INTEGER PRIMARY KEY,
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                classification TEXT NOT NULL DEFAULT 'internal',
                department TEXT NOT NULL,
                created_by INTEGER REFERENCES users(id),
                created_at REAL NOT NULL
            );
            CREATE TABLE IF NOT EXISTS access_grants (
                id INTEGER PRIMARY KEY,
                user_id INTEGER REFERENCES users(id),
                document_id INTEGER REFERENCES documents(id),
                permission_level INTEGER NOT NULL,
                granted_by INTEGER REFERENCES users(id),
                granted_at REAL NOT NULL,
                expires_at REAL,
                UNIQUE(user_id, document_id)
            );
            CREATE TABLE IF NOT EXISTS audit_log (
                id INTEGER PRIMARY KEY,
                user_id INTEGER,
                action TEXT NOT NULL,
                resource_id INTEGER,
                result TEXT NOT NULL,
                timestamp REAL NOT NULL
            );
        """)
        self.db.commit()

    def _hash_password(self, password, salt=None):
        if salt is None:
            salt = os.urandom(16)
        dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
        return salt.hex() + ':' + dk.hex()

    def _verify_password(self, password, stored_hash):
        salt_hex, _ = stored_hash.split(':')
        salt = bytes.fromhex(salt_hex)
        return hmac.compare_digest(
            self._hash_password(password, salt),
            stored_hash
        )

    def _generate_session_token(self):
        return os.urandom(32).hex()

    def _audit(self, user_id, action, resource_id, result):
        self.db.execute(
            "INSERT INTO audit_log (user_id, action, resource_id, result, timestamp) VALUES (?, ?, ?, ?, ?)",
            (user_id, action, resource_id, result, time.time())
        )
        self.db.commit()

    def authenticate(self, username, password):
        """Authenticate user and return session token."""
        cursor = self.db.execute(
            "SELECT id, password_hash, is_active FROM users WHERE username = ?",
            (username,)
        )
        user = cursor.fetchone()
        if not user or not user['is_active']:
            # Perform a dummy verification to keep timing constant and prevent
            # username enumeration via response-time analysis.
            self._verify_password(password, self._dummy_hash)
            self._audit(user['id'] if user else None, 'login_failed', None, 'denied')
            return None
        if not self._verify_password(password, user['password_hash']):
            self._audit(user['id'], 'login_failed', None, 'denied')
            return None

        token = self._generate_session_token()
        self._session_store[token] = {
            'user_id': user['id'],
            'username': username,
            'authenticated_at': time.time()
        }
        self._audit(user['id'], 'login', None, 'success')
        return token

    def _get_session(self, token):
        """Validate session token and return session data."""
        if not token or token not in self._session_store:
            return None
        session = self._session_store[token]
        # Sessions expire after 8 hours
        if time.time() - session['authenticated_at'] > 28800:
            del self._session_store[token]
            return None
        return session

    def _get_user_permission(self, user_id, document_id):
        """Get the effective permission level for a user on a document.

        Returns the permission_level from access_grants, or None if no grant exists.
        Checks expiration of grants.
        """
        cursor = self.db.execute(
            """SELECT permission_level, expires_at FROM access_grants 
               WHERE user_id = ? AND document_id = ?""",
            (user_id, document_id)
        )
        grant = cursor.fetchone()
        if not grant:
            return None
        # Check if grant has expired
        if grant['expires_at'] is not None and grant['expires_at'] < time.time():
            return None
        return grant['permission_level']

    def _get_department_permission(self, user_id, document_id):
        """Check if user has implicit read access via department membership."""
        cursor = self.db.execute(
            """SELECT d.department as doc_dept, u.department as user_dept
               FROM documents d, users u 
               WHERE d.id = ? AND u.id = ?""",
            (document_id, user_id)
        )
        row = cursor.fetchone()
        if row and row['doc_dept'] == row['user_dept']:
            return PERM_READ
        return PERM_NONE

    def _check_access(self, user_id, document_id, required_level):
        """Core authorization check. Returns True if user has sufficient permission.

        Permission resolution order:
        1. Explicit grant (access_grants table)
        2. Department-based implicit access (read only)
        3. Default deny
        """
        # Get explicit permission
        explicit_perm = self._get_user_permission(user_id, document_id)

        # Get department-based permission
        dept_perm = self._get_department_permission(user_id, document_id)

        # Resolve effective permission: explicit takes priority, fall back to department
        if explicit_perm is not None:
            effective_perm = explicit_perm
        else:
            effective_perm = dept_perm

        return effective_perm >= required_level

    def get_document(self, token, document_id):
        """Retrieve a document with full access control."""
        session = self._get_session(token)
        if not session:
            return {'status': 401, 'error': 'Authentication required'}

        user_id = session['user_id']

        # Validate document_id
        if not isinstance(document_id, int) or document_id < 1:
            return {'status': 400, 'error': 'Invalid document ID'}

        # Check document exists
        cursor = self.db.execute(
            "SELECT id, title, content, classification, department, created_by, created_at FROM documents WHERE id = ?",
            (document_id,)
        )
        doc = cursor.fetchone()
        if not doc:
            self._audit(user_id, 'read_document', document_id, 'not_found')
            return {'status': 404, 'error': 'Document not found'}

        # Authorization check
        if not self._check_access(user_id, document_id, PERM_READ):
            self._audit(user_id, 'read_document', document_id, 'denied')
            return {'status': 403, 'error': 'Access denied'}

        self._audit(user_id, 'read_document', document_id, 'granted')
        return {
            'status': 200,
            'document': {
                'id': doc['id'],
                'title': doc['title'],
                'content': doc['content'],
                'classification': doc['classification'],
                'department': doc['department']
            }
        }

    def update_document(self, token, document_id, new_content):
        """Update document content with write access control."""
        session = self._get_session(token)
        if not session:
            return {'status': 401, 'error': 'Authentication required'}

        user_id = session['user_id']

        if not isinstance(document_id, int) or document_id < 1:
            return {'status': 400, 'error': 'Invalid document ID'}

        if not isinstance(new_content, str) or len(new_content) > 1000000:
            return {'status': 400, 'error': 'Invalid content'}

        # Check document exists
        cursor = self.db.execute("SELECT id FROM documents WHERE id = ?", (document_id,))
        if not cursor.fetchone():
            return {'status': 404, 'error': 'Document not found'}

        # Authorization check - requires WRITE
        if not self._check_access(user_id, document_id, PERM_WRITE):
            self._audit(user_id, 'update_document', document_id, 'denied')
            return {'status': 403, 'error': 'Access denied'}

        self.db.execute(
            "UPDATE documents SET content = ? WHERE id = ?",
            (new_content, document_id)
        )
        self.db.commit()
        self._audit(user_id, 'update_document', document_id, 'granted')
        return {'status': 200, 'message': 'Document updated'}

    def share_document(self, token, document_id, target_user_id, permission_level):
        """Share a document with another user. Requires ADMIN on the document."""
        session = self._get_session(token)
        if not session:
            return {'status': 401, 'error': 'Authentication required'}

        user_id = session['user_id']

        if not isinstance(document_id, int) or document_id < 1:
            return {'status': 400, 'error': 'Invalid document ID'}
        if not isinstance(target_user_id, int) or target_user_id < 1:
            return {'status': 400, 'error': 'Invalid target user ID'}
        if permission_level not in (PERM_READ, PERM_WRITE, PERM_ADMIN):
            return {'status': 400, 'error': 'Invalid permission level'}

        # Verify target user exists
        cursor = self.db.execute("SELECT id FROM users WHERE id = ? AND is_active = 1", (target_user_id,))
        if not cursor.fetchone():
            return {'status': 404, 'error': 'Target user not found'}

        # Authorization check - requires ADMIN to share
        if not self._check_access(user_id, document_id, PERM_ADMIN):
            self._audit(user_id, 'share_document', document_id, 'denied')
            return {'status': 403, 'error': 'Access denied'}

        # Grant access
        self.db.execute(
            """INSERT OR REPLACE INTO access_grants 
               (user_id, document_id, permission_level, granted_by, granted_at, expires_at)
               VALUES (?, ?, ?, ?, ?, ?)""",
            (target_user_id, document_id, permission_level, user_id, time.time(), None)
        )
        self.db.commit()
        self._audit(user_id, 'share_document', document_id, 'granted')
        return {'status': 200, 'message': 'Access granted'}

    def list_department_documents(self, token, department=None):
        """List documents accessible to the user."""
        session = self._get_session(token)
        if not session:
            return {'status': 401, 'error': 'Authentication required'}

        user_id = session['user_id']

        # Get user's department
        cursor = self.db.execute("SELECT department FROM users WHERE id = ?", (user_id,))
        user = cursor.fetchone()
        if not user:
            return {'status': 404, 'error': 'User not found'}

        # Only show documents from user's own department or explicitly granted
        cursor = self.db.execute(
            """SELECT DISTINCT d.id, d.title, d.classification, d.department
               FROM documents d
               LEFT JOIN access_grants ag ON ag.document_id = d.id AND ag.user_id = ?
               WHERE d.department = ? OR ag.permission_level >= ?""",
            (user_id, user['department'], PERM_READ)
        )

        docs = [{'id': row['id'], 'title': row['title'], 
                 'classification': row['classification'],
                 'department': row['department']} for row in cursor.fetchall()]

        self._audit(user_id, 'list_documents', None, 'granted')
        return {'status': 200, 'documents': docs}
